// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./VaultExStorage.sol";

contract VaultExAccess is VaultExStorage {
    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    constructor(address token_, address root_, address feeWallet_, address hedgeVault_) VaultExStorage(token_, root_, feeWallet_, hedgeVault_) {}

    function _enforceChain() internal view {
        if (block.chainid != EXPECTED_CHAIN_ID) revert BadChain();
    }

    /// @notice Sets `owner` to `address(0)`; emit follows common Ownable pattern. Callable only by current `owner`.
    function renounceOwnership() external onlyOwner {
        address prev = owner;
        owner = address(0);
        emit OwnershipTransferred(prev, address(0));
    }

    /// @notice Protocol fee event kind: 1 deposit, 2 (unused), 3 (unused), 4 claimRank, 5 queue payout, 6 (unused), 7 `withdraw` from rewards balance. Claims do not emit protocol fee.
    /// @return net Amount after 5% protocol fee is transferred to `feeWallet`.
    /// @return fee Tokens sent to `feeWallet`.
    function _netAfterTxFee(uint256 gross, uint8 kind) internal returns (uint256 net, uint256 fee) {
        if (gross == 0) return (0, 0);
        fee = (gross * TX_FEE_BPS) / 10_000;
        net = gross - fee;
        if (fee > 0) {
            if (!token.transfer(feeWallet, fee)) revert TransferOut();
            emit ProtocolFee(feeWallet, fee, kind);
        }
    }

    /// @dev View-only helper for previews; must match `_netAfterTxFee`.
    function _previewTxFee(uint256 gross) internal view returns (uint256 net, uint256 fee) {
        if (gross == 0) return (0, 0);
        fee = (gross * TX_FEE_BPS) / 10_000;
        net = gross - fee;
    }
}

contracts/VaultExAntiAbuse.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./VaultExUsers.sol";

contract VaultExAntiAbuse is VaultExUsers {
    constructor(address token_, address root_, address feeWallet_, address hedgeVault_) VaultExUsers(token_, root_, feeWallet_, hedgeVault_) {}

    /// @param resolvedSponsor Sponsor address already stored on the user (`register` resolves id → address once).
    function _preflightDeposit(address resolvedSponsor) internal view {
        if (users[msg.sender].blocked) revert Blocked();
        // Root uses self-sponsor in storage; exempt from the normal self-sponsor check.
        if (msg.sender == rootSponsor) return;
        if (msg.sender == resolvedSponsor) revert SelfSponsor();
    }

    function _preflightRegister(uint256 sponsorRegisterId) internal view {
        if (users[msg.sender].blocked) revert Blocked();
        if (msg.sender == rootSponsor) return;
        address sp = _resolveSponsorByRegisterId(sponsorRegisterId);
        if (msg.sender == sp) revert SelfSponsor();
    }
}

contracts/VaultExConfig.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./VaultExAccess.sol";

contract VaultExConfig is VaultExAccess {
    constructor(address token_, address root_, address feeWallet_, address hedgeVault_) VaultExAccess(token_, root_, feeWallet_, hedgeVault_) {
        // Cycle investment ranges (in token units, e.g. 100e18 = $100)
        cycleMin[1] = 100e18;  cycleMax[1] = 1_000e18;   cycleRoiBps[1] = 50;
        cycleMin[2] = 200e18;  cycleMax[2] = 2_000e18;   cycleRoiBps[2] = 100;
        cycleMin[3] = 400e18;  cycleMax[3] = 4_000e18;   cycleRoiBps[3] = 150;
        cycleMin[4] = 800e18;  cycleMax[4] = 8_000e18;   cycleRoiBps[4] = 200;
        cycleMin[5] = 1_600e18; cycleMax[5] = 16_000e18; cycleRoiBps[5] = 225;
        cycleMin[6] = 3_200e18; cycleMax[6] = 32_000e18; cycleRoiBps[6] = 250;

        // cycleDuration[c] = 2 × (10_000 × 5 seconds) / cycleRoiBps[c]
        // = seconds to accrue 200% ROI at the cycle's per-5s rate; then the position auto-closes.
        //   C1: 2 × 50_000 / 50   = 2000 s
        //   C2: 2 × 50_000 / 100  = 1000 s
        //   …
        cycleDuration[1] = 2_000;
        cycleDuration[2] = 1_000;
        cycleDuration[3] = 666;
        cycleDuration[4] = 500;
        cycleDuration[5] = 444;
        cycleDuration[6] = 400;
    }

    function getCycleConfig(uint8 c) external view returns (uint256, uint256, uint16) {
        return (cycleMin[c], cycleMax[c], cycleRoiBps[c]);
    }
}

