contracts/VaultExDeposits.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./VaultExPayouts.sol";

contract VaultExDeposits is VaultExPayouts {
    constructor(address token_, address root_, address feeWallet_, address hedgeVault_) VaultExPayouts(token_, root_, feeWallet_, hedgeVault_) {}

    /// @notice One-time: set sponsor before the first `deposit`. Pass the sponsor’s 10-digit `registerId` (1_000_000_000–9_999_999_999), or `0` for protocol root.
    ///         Your own id is assigned pseudo-randomly in that range at registration.
    function register(uint256 sponsorRegisterId) external {
        _enforceChain();
        _preflightRegister(sponsorRegisterId);
        User storage u = users[msg.sender];
        if (u.exists) revert AlreadyRegistered();
        address sp = _resolveSponsorByRegisterId(sponsorRegisterId);
        u.exists = true;
        u.sponsor = sp;
        users[sp].directs += 1;
        directReferrals[sp].push(msg.sender);
        _indexRankContributionSource(msg.sender, sp);
        uint256 rid = _mintRandomRegisterId(msg.sender);
        registerIdOf[msg.sender] = rid;
        userByRegisterId[rid] = msg.sender;
        emit UserRegistered(msg.sender, rid, sp);
    }

    /// @dev Registers `newUser` as an individual contribution source for every ancestor in its referral chain.
    function _indexRankContributionSource(address newUser, address sponsor) internal {
        address cur = sponsor;
        uint256 guard;
        while (cur != address(0) && users[cur].exists && guard < 256) {
            rankContributionSources[cur].push(newUser);
            address next = users[cur].sponsor;
            if (next == cur) break;
            cur = next;
            unchecked {
                ++guard;
            }
        }
    }

    /// @notice One active investment per wallet; requires `register` first for new wallets.
    ///         Cycle ordering enforced (same cycle re-entry or exactly one cycle up).
    ///         All cap and ROI calculations use the GROSS deposit amount as principal.
    function deposit(uint8 cycle, uint256 amount) external {
        _enforceChain();
        User storage u = users[msg.sender];
        if (!u.exists) revert NotRegistered();
        _preflightDeposit(u.sponsor);
        if (u.hasActive) revert ActiveExists();
        if (cycle < 1 || cycle > 6) revert BadId();
        bool isFirstDeposit = (u.maxCycleReached == 0 && u.lastClosedCycle == 0);

        // ── Eligibility gate: previous cycle must be fully closed (auto-close after duration) ──
        if (u.lastClosedCycle != 0) {
            Position storage prev = activePosition[msg.sender];
            if (prev.active) revert ActiveExists();
        }

        // ── Cycle ordering (compare gross amounts) ───────────────────────
        uint8 lc = u.lastClosedCycle;
        if (cycle == lc) {
            if (amount < uint256(u.lastPrincipal)) revert ReEntryAmt();
        } else if (cycle == lc + 1) {
            if (amount < uint256(u.lastPrincipal) * 2) revert UpgradeAmt();
        } else {
            revert CycleOrder();
        }

        // ── Range check on gross amount ───────────────────────────────────
        if (amount < cycleMin[cycle] || amount > cycleMax[cycle]) revert Range();

        // Pull gross deposit; referrals use `grossPrincipal`, fee/hedge follow after.
        if (!token.transferFrom(msg.sender, address(this), amount)) revert TransferIn();
        uint256 grossPrincipal = amount;

        // ── Record position with GROSS principal ──────────────────────────
        //    Principal = full deposit (100), NOT the net after fee (95).
        //    All ROI accrual and cap checks (5× earnings, 2× ROI) use this gross amount.
        Position memory pMem;
        pMem.amount    = uint128(grossPrincipal);        // GROSS principal
        pMem.openedAt  = uint64(block.timestamp);
        pMem.lastRoiAt = uint64(block.timestamp);
        pMem.cycle     = cycle;
        pMem.active    = true;
        activePosition[msg.sender] = pMem;

        u.hasActive = true;
        if (cycle > u.maxCycleReached) u.maxCycleReached = cycle;

        totalDeposits += grossPrincipal;
        _bumpTurnover(grossPrincipal);

        // C1 obligation tracks `C1_OBLIGATION_MUL`× of the GROSS principal
        if (cycle == 1) {
            unchecked { c1RemainingObligation += grossPrincipal * C1_OBLIGATION_MUL; }
        }

        _propagateVolume(msg.sender, u.sponsor, grossPrincipal);
        // Network referral rewards are only generated on first registration deposit (initial C1),
        // and not on reinvest/re-entry deposits in later cycles.
        if (isFirstDeposit) {
            _payDirect(msg.sender, grossPrincipal, cycle);
            _payLevels(msg.sender, grossPrincipal, cycle);
        }

        (uint256 netAmount, ) = _netAfterTxFee(grossPrincipal, 1);
        uint256 toHedge  = netAmount * 50 / 100;
        uint256 retained = netAmount - toHedge;
        if (toHedge > 0) {
            if (!token.transfer(hedgeVault, toHedge)) revert TransferOut();
        }

        emit Deposit(msg.sender, grossPrincipal, cycle, u.sponsor);
        emit DepositSplit(hedgeVault, toHedge, retained);
        _postStateSync();
    }
}

contracts/VaultExPayouts.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./VaultExVolumeLifecycle.sol";

/// @dev Direct 10%, level 15%, ROI matching (accrued to `pendingRoiMatchingGross` until `claimRoiMatchingIncome`), and queueing.
contract VaultExPayouts is VaultExVolumeLifecycle {
    constructor(address token_, address root_, address feeWallet_, address hedgeVault_) VaultExVolumeLifecycle(token_, root_, feeWallet_, hedgeVault_) {}

    function _queueNetwork(address to, uint256 amt, uint8 kind, bool credit) internal {
        _pushPriorityQueue(QueueItem(to, uint128(amt), kind, PQ_NETWORK, RANK_META_NONE, credit));
        emit Queued(kind, to, amt);
    }

    /// @notice Withdraw `grossAmount` from your rewards balance (from ROI / referral / matching claims) to your wallet.
    /// @dev 5% protocol fee is taken on this transfer (not on claim). Rank bonuses are not held here.
    function withdraw(uint256 grossAmount) external {
        _enforceChain();
        User storage u = users[msg.sender];
        if (!u.exists || u.blocked) revert BadId();
        if (grossAmount == 0) revert ZeroWithdraw();
        if (grossAmount < MIN_WITHDRAW_GROSS) revert MinWithdraw();
        if (withdrawableGross[msg.sender] < grossAmount) revert InsufficientWithdrawBalance();
        if (token.balanceOf(address(this)) < grossAmount) revert PoolLow();

        withdrawableGross[msg.sender] -= grossAmount;
        (uint256 netToUser, ) = _netAfterTxFee(grossAmount, 7);
        unchecked {
            totalWithdrawals += netToUser;
            u.totalWithdrawn += netToUser;
        }
        if (!token.transfer(msg.sender, netToUser)) revert TransferOut();
        emit RewardsWithdrawn(msg.sender, grossAmount, netToUser);
        _pokeEmergency();
    }

    function _effectiveCycle(uint8 uCycle, uint8 dCycle) internal pure returns (uint8) {
        return uCycle < dCycle ? uCycle : dCycle;
    }

    /// @dev Returns the ROI base for matching after applying `effectiveCycle = min(parentCycle, childCycle)`.
    ///      This scales the claimant ROI by the ratio of effective-cycle ROI rate to child-cycle ROI rate,
    ///      so uplines never earn matching as if they were in a higher cycle than allowed.
    function _matchingRoiBase(address upline, uint8 childCycle, uint256 claimedRoiGross) internal view returns (uint256) {
        if (claimedRoiGross == 0) return 0;
        if (upline == rootSponsor || childCycle == 0) return claimedRoiGross;

        uint8 parentCycle = activePosition[upline].cycle;
        if (parentCycle == 0) parentCycle = users[upline].maxCycleReached;
        if (parentCycle == 0) return 0;

        uint8 effectiveCycle = _effectiveCycle(parentCycle, childCycle);
        uint256 childBps = uint256(cycleRoiBps[childCycle]);
        uint256 effectiveBps = uint256(cycleRoiBps[effectiveCycle]);
        if (childBps == 0 || effectiveBps >= childBps) return claimedRoiGross;
        return (claimedRoiGross * effectiveBps) / childBps;
    }

    function _eligibleUpline(address u) internal view returns (bool) {
        if (!users[u].exists || users[u].blocked) return false;
        if (u == rootSponsor) return true;
        return activePosition[u].active;
    }

    /// @dev ROI-on-ROI only: upline must still accrue ROI (under earnings + ROI caps), except root (always eligible).
    function _eligibleUplineRoiMatching(address u) internal view returns (bool) {
        if (!users[u].exists || users[u].blocked) return false;
        if (u == rootSponsor) return true;
        Position storage p = activePosition[u];
        if (!p.active) return false;
        uint256 totalCap = uint256(p.amount) * POSITION_EARNINGS_CAP_MUL;
        uint256 roiCap = uint256(p.amount) * POSITION_ROI_CAP_MUL;
        return p.paidTotal < totalCap && p.roiPaid < roiCap;
    }

    function _levelUnlock(address upline, uint256 depthFromDepositor) internal view returns (bool) {
        if (upline == rootSponsor) return true;
        uint32 d = users[upline].directs;
        if (depthFromDepositor <= 3) return d >= 2;
        if (depthFromDepositor <= 6) return d >= 3;
        if (depthFromDepositor <= 10) return d >= 4;
        return d >= 5;
    }

    /// @notice Claim pending direct + level income into `withdrawableGross` (then `withdraw` to wallet; fee on withdraw).
    /// @dev Uses the same cap and fee accounting model as other non-ROI payouts.
    function claimReferralIncome() external {
        _enforceChain();
        User storage u = users[msg.sender];
        if (!u.exists || u.blocked) revert BadId();
        Position storage p = activePosition[msg.sender];
        if (msg.sender != rootSponsor && !p.active) revert NoActive();

        uint256 directPending = pendingDirectReferralGross[msg.sender];
        uint256 levelPending = pendingLevelIncomeGross[msg.sender];
        uint256 gross = directPending + levelPending;
        if (gross == 0) revert NothingToClaim();

        uint256 payableGross = _capNonRoiCredit(msg.sender, p, gross);
        if (payableGross == 0) {
            if (gross > 0) {
                pendingDirectReferralGross[msg.sender] = 0;
                pendingLevelIncomeGross[msg.sender] = 0;
                lostReferralGross[msg.sender] += gross;
                emit ReferralRewardsLost(msg.sender, gross);
            }
            _closeIfNeeded(msg.sender, p);
            if (!p.active) return;
            revert Cap();
        }

        uint256 takeDirect = directPending;
        if (takeDirect > payableGross) takeDirect = payableGross;
        uint256 takeLevel = payableGross - takeDirect;

        uint256 directRemain = directPending - takeDirect;
        uint256 levelRemain = levelPending - takeLevel;
        pendingDirectReferralGross[msg.sender] = 0;
        pendingLevelIncomeGross[msg.sender] = 0;
        uint256 overflow = directRemain + levelRemain;
        if (overflow > 0) {
            lostReferralGross[msg.sender] += overflow;
            emit ReferralRewardsLost(msg.sender, overflow);
        }

        _deliverOrQueue(msg.sender, payableGross, 2, true);
        emit ReferralIncomeClaimed(msg.sender, payableGross, (payableGross * (10_000 - TX_FEE_BPS)) / 10_000);
        _postStateSync();
    }

    /// @notice Claim accrued ROI-on-ROI (matching) gross balance into `withdrawableGross` (same cap rules as referral income; fee on withdraw).
    function claimRoiMatchingIncome() external {
        _enforceChain();
        User storage u = users[msg.sender];
        if (!u.exists || u.blocked) revert BadId();
        Position storage p = activePosition[msg.sender];
        if (msg.sender != rootSponsor && !p.active) revert NoActive();

        uint256 gross = pendingRoiMatchingGross[msg.sender];
        if (gross == 0) revert NothingToClaim();

        uint256 payableGross = _capNonRoiCredit(msg.sender, p, gross);
        if (payableGross == 0) {
            pendingRoiMatchingGross[msg.sender] = 0;
            lostRoiMatchingGross[msg.sender] += gross;
            emit RoiMatchingLost(msg.sender, gross);
            _closeIfNeeded(msg.sender, p);
            if (!p.active) return;
            revert Cap();
        }

        uint256 overflow = gross - payableGross;
        pendingRoiMatchingGross[msg.sender] = 0;
        if (overflow > 0) {
            lostRoiMatchingGross[msg.sender] += overflow;
            emit RoiMatchingLost(msg.sender, overflow);
        }

        _deliverOrQueue(msg.sender, payableGross, 6, true);
        emit RoiMatchingClaimed(msg.sender, payableGross, (payableGross * (10_000 - TX_FEE_BPS)) / 10_000);
        _postStateSync();
    }

    function _payDirect(address depositor, uint256 grossDeposit, uint8 depCycle) internal {
        address u = users[depositor].sponsor;
        uint256 pay = grossDeposit * 10 / 100;
        bool paid;
        uint256 guard;
        while (u != address(0) && users[u].exists && guard < 256) {
            unchecked {
                ++guard;
            }
            if (_eligibleUpline(u)) {
                uint8 ec = u == rootSponsor ? depCycle : _effectiveCycle(users[u].maxCycleReached, depCycle);
                uint256 a = pay * uint256(ec) / uint256(depCycle);
                if (a == 0) a = pay;
                pendingDirectReferralGross[u] += a;
                emit ReferralIncomeAccrued(u, a, 2);
                paid = true;
                break;
            }
            address nextU = users[u].sponsor;
            if (nextU == u) break;
            u = nextU;
        }
        if (!paid && pay > 0) {
            lostReferralGross[depositor] += pay;
            emit ReferralRewardsLost(depositor, pay);
        }
    }

    function _payLevels(address depositor, uint256 grossDeposit, uint8 depCycle) internal {
        address u = users[depositor].sponsor;
        uint256 depth = 1;
        while (u != address(0) && users[u].exists && depth <= 15) {
            if (depth >= 2 && _levelUnlock(u, depth)) {
                // Pay exact percentages of the depositor's GROSS amount (basis points):
                // L2 4%, L3 2%, L4 1.5%, L5 1.5%, L6 1%, L7 1%, L8 0.75%, L9 0.75%, L10 0.75%,
                // L11 0.5%, L12 0.5%, L13 0.5%, L14 0.5%, L15 0.25%.
                // `_levelWeight()` returns these as BPS: 400,200,150,...,25.
                uint256 bps = _levelWeight(depth - 2);
                uint256 pay = (grossDeposit * bps) / 10_000;
                uint8 ec = u == rootSponsor ? depCycle : _effectiveCycle(users[u].maxCycleReached, depCycle);
                pay = (pay * uint256(ec)) / uint256(depCycle);
                if (pay > 0) {
                    if (_eligibleUpline(u)) {
                        pendingLevelIncomeGross[u] += pay;
                        emit ReferralIncomeAccrued(u, pay, 3);
                    } else {
                        lostReferralGross[depositor] += pay;
                        emit ReferralRewardsLost(depositor, pay);
                    }
                }
            }
            address nextU = users[u].sponsor;
            if (nextU == u) break;
            u = nextU;
            unchecked {
                depth++;
            }
        }
    }

    function _roiMatchingSharePct(uint256 depthIdx) private pure returns (uint8) {
        if (depthIdx == 0) return 5;
        if (depthIdx == 1) return 2;
        return 1; // levels 3-15
    }

    /// @return matchingAccruedGross Sum of matching shares credited to uplines' `pendingRoiMatchingGross` (not lost).
    function _roiMatching(address roiUser, uint256 roiGross) internal returns (uint256 matchingAccruedGross) {
        if (roiGross == 0) return 0;
        address u = users[roiUser].sponsor;
        uint8 childCycle = activePosition[roiUser].cycle;
        uint256 lost;
        for (uint256 i = 0; i < 15; i++) {
            // ROI-on-ROI is paid as a percentage of the claimant's ROI after cycle clipping:
            // matchingBase = claimedROI × cycleRoiBps[min(parentCycle, childCycle)] / cycleRoiBps[childCycle]
            // share = matchingBase × levelPct
            // This keeps one-shot accumulated claims proportional and avoids per-day recomputation.
            uint256 matchingBase = _matchingRoiBase(u, childCycle, roiGross);
            // Level shares:
            // L1 5%, L2 2%, L3 1%, L4-L15 1% each.
            uint256 share = (matchingBase * uint256(_roiMatchingSharePct(i))) / 100;
            if (share == 0) {
                if (u != address(0) && users[u].exists) u = users[u].sponsor;
                continue;
            }
            if (u == address(0) || !users[u].exists) {
                lost += share;
            } else if (_eligibleUplineRoiMatching(u)) {
                pendingRoiMatchingGross[u] += share;
                matchingAccruedGross += share;
                emit RoiMatchingAccrued(u, share, roiUser);
                u = users[u].sponsor;
            } else {
                lost += share;
                u = users[u].sponsor;
            }
        }
        if (lost > 0) {
            lostRoiMatchingGross[roiUser] += lost;
            emit RoiMatchingLost(roiUser, lost);
        }
    }

    function _recordNonRoiOverflowLost(address to, uint8 kind, uint256 overflow) internal {
        if (overflow == 0) return;
        if (kind == 2 || kind == 3) {
            lostReferralGross[to] += overflow;
            emit ReferralRewardsLost(to, overflow);
            return;
        }
        if (kind == 6) {
            lostRoiMatchingGross[to] += overflow;
            emit RoiMatchingLost(to, overflow);
        }
    }

    function _deliverOrQueue(address to, uint256 amt, uint8 kind, bool credit) internal {
        if (amt == 0) return;
        Position storage p = activePosition[to];
        // Root may claim network income without an open position; credits go straight to `withdrawableGross` when liquid.
        if (to == rootSponsor && !p.active && credit) {
            if (emergencyMode) {
                _queueNetwork(to, amt, kind, credit);
                return;
            }
            if (token.balanceOf(address(this)) < amt) {
                _queueNetwork(to, amt, kind, credit);
                return;
            }
            _creditWithdrawableGross(to, amt);
            _postStateSync();
            return;
        }
        if (emergencyMode) {
            if (!p.active) {
                _queueNetwork(to, amt, kind, credit);
                return;
            }
            uint256 requested = amt;
            amt = _capNonRoiCredit(to, p, amt);
            if (amt == 0) {
                _closeIfNeeded(to, p);
                _recordNonRoiOverflowLost(to, kind, requested);
                return;
            }
            _recordNonRoiOverflowLost(to, kind, requested - amt);
            _queueNetwork(to, amt, kind, credit);
            return;
        }
        if (!p.active) {
            _queueNetwork(to, amt, kind, credit);
            return;
        }
        uint256 requested = amt;
        amt = _capNonRoiCredit(to, p, amt);
        if (amt == 0) {
            _closeIfNeeded(to, p);
            _recordNonRoiOverflowLost(to, kind, requested);
            return;
        }
        _recordNonRoiOverflowLost(to, kind, requested - amt);

        if (token.balanceOf(address(this)) < amt) {
            _queueNetwork(to, amt, kind, credit);
            return;
        }

        // Direct + level + ROI matching claims: full gross credits `withdrawableGross` (fee on `withdraw` only).
        // `amt` is the GROSS credit used for cap accounting and queue amounts.
        _creditWithdrawableGross(to, amt);
        p.paidTotal += uint128(amt);
        if (p.cycle == 1) _c1Paydown(amt);
        _closeIfNeeded(to, p);
    }
}

