contracts/VaultExRoi.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./VaultExDeposits.sol";

contract VaultExRoi is VaultExDeposits {
    constructor(address token_, address root_, address feeWallet_, address hedgeVault_) VaultExDeposits(token_, root_, feeWallet_, hedgeVault_) {}

    function _currentRoiBps(Position storage p) private view returns (uint256) {
        return emergencyMode ? uint256(50) : uint256(cycleRoiBps[p.cycle]);
    }

    /// @dev True when the position has reached either terminal payout boundary.
    function _isCapClosed(Position storage p, uint256 totalCap, uint256 roiCap) internal view returns (bool) {
        return uint256(p.paidTotal) >= totalCap || uint256(p.roiPaid) >= roiCap;
    }

    function _consumeElapsedPeriods(Position storage p, uint256 lastTs, uint256 periods) private {
        p.lastRoiAt = periods > 0
            ? uint64(lastTs + periods * ROI_CLAIM_PERIOD)
            : uint64(block.timestamp);
    }

    function _capRoom(Position storage p, uint256 totalCap, uint256 roiCap, uint256 roiQueued)
        private
        view
        returns (uint256)
    {
        uint256 roiPaid_ = uint256(p.roiPaid);
        uint256 roiRoom = roiCap > roiPaid_ ? roiCap - roiPaid_ : 0;
        if (roiRoom > roiQueued) roiRoom -= roiQueued;
        else roiRoom = 0;

        uint256 paidTotal_ = uint256(p.paidTotal);
        uint256 effectiveTotalCap = emergencyMode ? uint256(p.amount) : totalCap;
        uint256 totalRoom = effectiveTotalCap > paidTotal_ ? effectiveTotalCap - paidTotal_ : 0;
        if (totalRoom > roiQueued) totalRoom -= roiQueued;
        else totalRoom = 0;

        return roiRoom < totalRoom ? roiRoom : totalRoom;
    }

    function _closingRoiGross(Position storage p, uint256 room) internal view returns (uint256 gross) {
        uint256 elapsed = uint256(p.closedAt) - uint256(p.lastRoiAt);
        uint256 bps = uint256(cycleRoiBps[p.cycle]);
        gross = (uint256(p.amount) * bps * elapsed) / (10_000 * ROI_RATE_PERIOD_SECONDS);
        if (gross > room) gross = room;
    }

    function _queueRoiGross(address user, Position storage p, uint256 alreadyQueued, uint256 gross) private {
        uint256 queued = alreadyQueued + gross;
        if (queued > type(uint128).max) revert QueueOverflow();
        uint8 priority = _roiEmergencyPriority(user, p);
        _pushPriorityQueue(QueueItem(user, uint128(gross), 3, priority, RANK_META_NONE, false));
        roiQueuedGross[user] = uint128(queued);
    }

    function _applyRoiPayout(Position storage p, uint256 gross) private {
        p.roiPaid += uint128(gross);
        p.paidTotal += uint128(gross);
    }

    function _flushAndClose(Position storage p) private {
        _postStateSync();
        _closeIfNeeded(msg.sender, p);
    }

    function _queueAndExit(Position storage p, uint256 roiQ, uint256 gross) private {
        _queueRoiGross(msg.sender, p, roiQ, gross);
        _flushAndClose(p);
    }

    function _accrualStep(Position storage p, uint256 elapsed) private view returns (uint256 perPeriodGross, uint256 periods) {
        periods = elapsed / ROI_CLAIM_PERIOD;
        if (periods == 0) return (0, 0);
        uint256 perRateGross = (uint256(p.amount) * _currentRoiBps(p)) / 10_000;
        if (perRateGross == 0) perRateGross = 1;
        perPeriodGross = perRateGross * (ROI_CLAIM_PERIOD / ROI_RATE_PERIOD_SECONDS);
    }

    // ─── ROI accrual math ────────────────────────────────────────────────────

    /// @dev Computes gross ROI for `elapsed` seconds of an active position.
    ///      Both the ROI cap (2× principal) and earnings cap (5× principal) are respected.
    ///      Special case: when the remaining cap room is smaller than one full period's ROI the
    ///      position would get permanently stuck because integer periods always round to 0. In
    ///      that case we return the exact remaining cap dust so `_closeIfNeeded` can fire.
    function _accruedRoiGross(
        Position storage p,
        uint256 elapsed,
        uint256 totalCap,
        uint256 roiQueued
    )
        internal
        view
        returns (uint256 gross, uint256 periods)
    {
        uint256 roiCap = uint256(p.amount) * POSITION_ROI_CAP_MUL;
        uint256 perPeriodGross;
        (perPeriodGross, periods) = _accrualStep(p, elapsed);
        if (periods == 0) return (0, 0);
        uint256 capRoom = _capRoom(p, totalCap, roiCap, roiQueued);
        uint256 maxPeriodsByCap = capRoom / perPeriodGross;
        if (periods > maxPeriodsByCap) periods = maxPeriodsByCap;
        gross = periods * perPeriodGross;
        // Dust settlement: capRoom < one period → pay the exact remainder so the position
        // can eventually close rather than being stuck forever at the cap boundary.
        if (gross == 0 && capRoom > 0 && elapsed >= ROI_CLAIM_PERIOD) {
            gross = capRoom;
        }
    }

    // ─── Post-close ROI settlement ───────────────────────────────────────────

    /// @dev Pays the ROI that accrued between `lastRoiAt` and `closedAt` AFTER the position
    ///      has been finalized.
    ///
    ///      Important: this settlement MUST still respect the 5× earnings cap, because a user can
    ///      reach the earnings cap via non-ROI credits (rank/referral/matching). In that case ROI
    ///      must stop immediately for the rest of the cycle, including after the close timestamp.
    ///
    ///      Uses pro-rata (continuous) accrual so not a single second of earned ROI is lost,
    ///      but is bounded by BOTH:
    ///        • ROI cap (2× principal)
    ///        • Earnings cap (5× principal)
    function _settleClosingRoi(Position storage p, uint256 totalCap, uint256 roiCap) internal {
        uint256 closedAt  = uint256(p.closedAt);
        uint256 lastRoiAt = uint256(p.lastRoiAt);
        if (closedAt <= lastRoiAt) return;

        uint256 room = _capRoom(p, totalCap, roiCap, 0);
        if (room == 0) {
            p.lastRoiAt = uint64(closedAt);
            return;
        }

        uint256 gross = _closingRoiGross(p, room);

        // Mark settled before any transfer to prevent re-entry / repeat claims.
        p.lastRoiAt = uint64(closedAt);

        if (gross == 0) return;
        if (token.balanceOf(address(this)) < gross) revert PoolLow();

        _applyRoiPayout(p, gross);

        _creditWithdrawableGross(msg.sender, gross);
        uint256 matchingAccrued;
        // If this settlement reaches the cap boundary, stop further reward propagation from this cycle.
        if (!emergencyMode && !_isCapClosed(p, totalCap, roiCap)) matchingAccrued = _roiMatching(msg.sender, gross);
        uint256 netIfWithdrawNow = (gross * (10_000 - TX_FEE_BPS)) / 10_000;
        emit RoiClaimed(msg.sender, gross, netIfWithdrawNow, matchingAccrued);
        _pokeEmergency();
    }

    /// @dev When the cycle duration has elapsed: auto-close, principal pay/queue, optional closing ROI.
    function _finalizeMatureCycleIfDue(Position storage p, uint256 totalCap, uint256 roiCap) private {
        if (_isTimeLocked(p)) return;
        _closeIfNeeded(msg.sender, p);
        if (p.amount > 0 && p.closedAt > p.lastRoiAt && p.roiPaid < roiCap) {
            _settleClosingRoi(p, totalCap, roiCap);
        }
        _postStateSync();
    }

    function _dashboardClaimableRoi(Position storage p, uint256 elapsed, uint256 totalCap, address user)
        private
        view
        returns (uint256 gross)
    {
        (gross, ) = _accruedRoiGross(p, elapsed, totalCap, roiQueuedGross[user]);
    }

    // ─── claimRoi ────────────────────────────────────────────────────────────

    /// @notice Claim accumulated ROI.
    ///
    ///  Lifecycle rules:
    ///  • Before any cap is reached, ROI accrues in `ROI_CLAIM_PERIOD` claim steps (rate is per `ROI_RATE_PERIOD_SECONDS`).
    ///  • Once paidTotal reaches 5× (or roiPaid reaches 2× principal): position closes immediately
    ///    and the user becomes eligible for the next cycle (no separate principal payout).
    ///  • Calling `claimRoi` after the position is closed settles any ROI that accrued
    ///    between the last live claim and the close timestamp (pro-rata, bounded by ROI cap and earnings cap).
    ///  • Gross amounts credit `withdrawableGross` (no fee); 5% fee applies on `withdraw` to wallet
    ///    where minimum-withdraw validation is enforced.
    function claimRoi() external {
        _enforceChain();
        if (users[msg.sender].blocked) revert Blocked();

        Position storage p = activePosition[msg.sender];

        uint256 totalCap = uint256(p.amount) * POSITION_EARNINGS_CAP_MUL;
        uint256 roiCap   = uint256(p.amount) * POSITION_ROI_CAP_MUL;

        // ── Post-close: settle leftover ROI ─────────────────────────────
        if (!p.active) {
            if (p.amount > 0 && p.closedAt > p.lastRoiAt && p.roiPaid < roiCap) {
                _settleClosingRoi(p, totalCap, roiCap);
            }
            return;
        }

        // ── If already reached cap → close ─────────────────────────────
        if (p.paidTotal >= totalCap || p.roiPaid >= roiCap) {
            _closeIfNeeded(msg.sender, p);
            return;
        }

        // ── If cycle ended → finalize ──────────────────────────────────
        if (!_isTimeLocked(p)) {
            _finalizeMatureCycleIfDue(p, totalCap, roiCap);
            return;
        }

        uint256 lastTs  = uint256(p.lastRoiAt);
        uint256 elapsed = block.timestamp - lastTs;

        if (elapsed < ROI_CLAIM_PERIOD) revert NotDue();

        uint256 roiQ = roiQueuedGross[msg.sender];

        // ✅ Use SAFE function (handles cap + dust)
        (uint256 grossAccrued, uint256 periods) = _accruedRoiGross(
            p,
            elapsed,
            totalCap,
            roiQ
        );

        // ── Handle edge case: still zero ───────────────────────────────
        if (grossAccrued == 0) {
            p.lastRoiAt = uint64(block.timestamp);
            _closeIfNeeded(msg.sender, p);
            return;
        }

        // ── Emergency Mode ─────────────────────────────────────────────
        if (emergencyMode) {
            _consumeElapsedPeriods(p, lastTs, periods);
            _queueAndExit(p, roiQ, grossAccrued);
            return;
        }

        // ── Normal Flow ────────────────────────────────────────────────
        _consumeElapsedPeriods(p, lastTs, periods);

        if (token.balanceOf(address(this)) < grossAccrued) {
            _queueAndExit(p, roiQ, grossAccrued);
            return;
        }

        // ── Apply earnings ─────────────────────────────────────────────
        _applyRoiPayout(p, grossAccrued);

        if (p.cycle == 1) _c1Paydown(grossAccrued);

        _creditWithdrawableGross(msg.sender, grossAccrued);

        uint256 matchingAccrued;

        // Stop matching if cap reached
        if (!_isCapClosed(p, totalCap, roiCap)) {
            matchingAccrued = _roiMatching(msg.sender, grossAccrued);
        }

        uint256 netIfWithdrawNow = (grossAccrued * (10_000 - TX_FEE_BPS)) / 10_000;

        emit RoiClaimed(msg.sender, grossAccrued, netIfWithdrawNow, matchingAccrued);

        // ── Final close check ──────────────────────────────────────────
        _closeIfNeeded(msg.sender, p);
        _pokeEmergency();
    }

    function getUserRoiDashboard(address user)
        external
        view
        returns (
            uint256 deposit,
            uint8 cycle,
            uint256 roiPaid,
            uint256 claimableRoi,
            uint256 roiRemaining,
            uint256 cycleEndTime,
            bool active
        )
    {
        Position storage p = activePosition[user];

        deposit = p.amount;
        cycle = p.cycle;
        roiPaid = p.roiPaid;
        active = p.active;

        if (!p.active) {
            return (deposit, cycle, roiPaid, 0, 0, p.closedAt, false);
        }

        uint256 totalCap = uint256(p.amount) * POSITION_EARNINGS_CAP_MUL;
        uint256 roiCap = uint256(p.amount) * POSITION_ROI_CAP_MUL;
        uint256 elapsed = block.timestamp - uint256(p.lastRoiAt);
        if (elapsed >= ROI_CLAIM_PERIOD) {
            claimableRoi = _dashboardClaimableRoi(p, elapsed, totalCap, user);
        }

        roiRemaining = roiCap > roiPaid ? roiCap - roiPaid : 0;
        cycleEndTime = uint256(p.lastRoiAt) + cycleDuration[p.cycle];
    }
}

contracts/VaultExStorage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./IVaultExToken.sol";

/// @dev Base storage, types, constants, and protocol events/errors.
contract VaultExStorage {
    IVaultExToken internal immutable token;
    /// @dev Deployer; may be cleared via `renounceOwnership` in `VaultExAccess`. Same slot as legacy layouts.
    address public owner;
    address public rootSponsor;

    /// @dev Receives 50% of each deposit (after protocol fee). Set at deploy.
    address public hedgeVault;

    uint256 internal constant EXPECTED_CHAIN_ID = 97;

    bool public emergencyMode;
    uint64 public emergencyActivatedAt;
    uint64 public emergencyClearedAt;
    uint256 internal athTurnover;
    uint256 internal turnover;
    uint256 public c1RemainingObligation;

    uint256 internal totalDeposits;
    uint256 public totalWithdrawals;

    /// @dev Cumulative ROI + non-ROI credits stop at `amount × POSITION_EARNINGS_CAP_MUL`.
    uint256 internal constant POSITION_EARNINGS_CAP_MUL = 5;
    /// @dev Gross ROI credited to `roiPaid` stops at `amount × POSITION_ROI_CAP_MUL`.
    uint256 internal constant POSITION_ROI_CAP_MUL = 2;
    /// @dev No separate non-ROI sub-cap; all reward streams are bounded by the total earnings cap.
    /// @dev `cycleRoiBps` expresses ROI per `ROI_RATE_PERIOD_SECONDS` (pro-rata + cycle duration math).
    uint256 internal constant ROI_RATE_PERIOD_SECONDS = 5;
    /// @dev Minimum time between `claimRoi` calls; discrete accrual steps align to this period.
    uint256 internal constant ROI_CLAIM_PERIOD = 1 minutes;
    /// @dev Minimum gross amount (5 token units, 18 decimals) enforced only in `withdraw`.
    uint256 internal constant MIN_WITHDRAW_GROSS = 5e18;
    /// @dev C1 pool obligation added on deposit (`amount × this`).
    uint256 internal constant C1_OBLIGATION_MUL = 4;

    /// @notice 5% fee on deposit, `withdraw` from rewards balance, rank claim, and direct rank queue payouts (constant). Claims credit gross without fee.
    uint16 internal constant TX_FEE_BPS = 500;
    address internal feeWallet;

    struct User {
        address sponsor;
        bool exists;
        bool blocked;
        uint8 maxCycleReached;
        uint8 lastClosedCycle;
        uint32 directs;
        uint128 lastPrincipal;      // gross principal of the last closed position
        bool hasActive;
        uint256 groupVolume;
        uint256 maxLegVolume;
        uint256 totalWithdrawn;
        uint16 rankClaimedMask;
    }

    struct Position {
        uint128 amount;        // GROSS deposit (before fee); used as the reference principal for all caps/ROI
        uint64 openedAt;
        uint64 lastRoiAt;
        uint8 cycle;
        bool active;
        bool principalWithdrawn; // close latch (legacy layout compatibility)
        uint128 paidTotal;     // cumulative credits toward earnings cap (ROI + non-ROI; principal not included)
        uint128 roiPaid;       // cumulative gross ROI toward ROI cap
        uint64 closedAt;       // timestamp set by _finalizeClose; enables post-close ROI settlement
    }

    mapping(address => User) internal users;
    mapping(address => Position) internal activePosition;
    mapping(address => mapping(address => uint256)) internal legVolume;
    /// @dev Cumulative business volume credited from `depositor` to `ancestor` (across all deposits).
    mapping(address => mapping(address => uint256)) internal contributorVolume;

    /// @notice Ten-digit register ids: [`REGISTER_ID_MIN`, `REGISTER_ID_MAX`]. Root gets `REGISTER_ID_MIN` at deploy.
    uint256 internal constant REGISTER_ID_MIN = 1_000_000_000;
    uint256 internal constant REGISTER_ID_MAX = 9_999_999_999;

    /// @dev Increments on each successful `register`; mixed into pseudo-random id draws (not the id itself).
    uint256 public registerIdNonce;
    /// @dev `0` = never registered; root uses `REGISTER_ID_MIN` (10-digit).
    mapping(address => uint256) public registerIdOf;
    mapping(uint256 => address) public userByRegisterId;

    /// @dev Direct referrals: users who called `register(sponsorRegisterId)` with this address as resolved sponsor (registration order).
    mapping(address => address[]) internal directReferrals;
    /// @dev Flattened full-tree downline list per ancestor (each user is added once at registration).
    mapping(address => address[]) internal rankContributionSources;

    /// @dev Emergency payout priority: 1=C1 recovery (withdrawn < principal), 2–6=cycle ROI,
    ///      7=network (direct/level/matching), 8=rank rewards.
    struct QueueItem {
        address user;
        uint128 amount;
        uint8 kind;
        uint8 priority;
        uint8 rankMeta; // rank 0–7 when `priority == 8`; `RANK_META_NONE` otherwise
        bool creditPosition;
    }

    /// @dev `priorityQueues[priority]` is FIFO; valid priorities are 1–8 inclusive.
    mapping(uint8 => QueueItem[]) internal priorityQueues;

    /// @dev Gross amount still owed across all priority queues (before protocol fee on payout).
    uint256 public pendingQueuedWithdrawals;

    /// @dev ROI gross queued but not yet paid (counts toward ROI cap room for `claimRoi` accrual).
    mapping(address => uint128) internal roiQueuedGross;

    /// @dev Non-zero = user has a rank reward waiting in PQ 8 (`value - 1` is the rank index 0–7).
    mapping(address => uint8) internal pendingRankClaim;

    /// @dev Cumulative gross direct+level referral amounts not paid on this user's deposits (no eligible upline in chain).
    mapping(address => uint256) public lostReferralGross;

    /// @dev Cumulative gross ROI-matching amounts not paid on this user's ROI claims (uplines inactive / chain too short).
    mapping(address => uint256) public lostRoiMatchingGross;
    
    /// @dev Accrued direct-referral gross rewards awaiting manual claim by receiver.
    mapping(address => uint256) public pendingDirectReferralGross;

    /// @dev Accrued level-income gross rewards awaiting manual claim by receiver.
    mapping(address => uint256) public pendingLevelIncomeGross;

    /// @dev Accrued ROI-on-ROI (matching) gross rewards awaiting manual claim by receiver.
    mapping(address => uint256) public pendingRoiMatchingGross;

    /// @dev Gross rewards credited from `claimRoi`, `claimReferralIncome`, and `claimRoiMatchingIncome` (no fee on claim).
    ///      5% fee applies when calling `withdraw`. Rank bonuses (`claimRank`) are not stored here — those still pay directly.
    mapping(address => uint256) public withdrawableGross;

    uint8 internal constant RANK_META_NONE = type(uint8).max;

    uint8 internal constant PQ_C1_RECOVERY = 1;
    uint8 internal constant PQ_NETWORK = 7;
    uint8 internal constant PQ_RANK = 8;

    uint256[7] internal cycleMin;
    uint256[7] internal cycleMax;
    uint16[7] internal cycleRoiBps;
    /// @notice Time (in seconds) a position must remain open before it auto-closes.
    ///         Computed as 2 × (10_000 × ROI_RATE_PERIOD_SECONDS) / cycleRoiBps[c] — seconds to accrue 200% ROI at the cycle rate.
    uint256[7] internal cycleDuration;

    error BadChain();
    error NotOwner();
    error Blocked();
    error SelfSponsor();
    error TransferIn();
    error Range();
    error ActiveExists();
    error NoActive();
    error CycleOrder();
    error ReEntryAmt();
    error UpgradeAmt();
    error Cap();
    error EmergencyManualDisabled();
    error RankClaimAlreadyPending();
    error RankAlreadyClaimed();
    error NotDue();
    error BadId();
    error PoolLow();
    error NotRegistered();
    error AlreadyRegistered();
    error NothingToClaim();
    error MinWithdraw();
    error InsufficientWithdrawBalance();
    error ZeroWithdraw();
    error BadSponsorId();
    error RegisterIdsExhausted();
    error ZeroAddress();
    error ZeroAmount();
    error TransferOut();
    error QueueOverflow();
    error InvalidQueuePriority();
    error InvalidCycle();

    event FeeWalletUpdated(address indexed prev, address indexed next);
    event HedgeVaultUpdated(address indexed prev, address indexed next);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event UserRegistered(address indexed user, uint256 registerId, address indexed sponsor);
    event Deposit(address indexed user, uint256 amount, uint8 cycle, address indexed sponsor);
    event DepositSplit(address indexed hedge, uint256 toHedge, uint256 retained);
    /// @param matchingPaid Gross ROI-on-ROI shares credited to uplines' `pendingRoiMatchingGross` this claim (not sent in this tx).
    /// @param netIfWithdrawNow Preview: net to wallet if user `withdraw`s this claim's gross in one tx (5% fee on withdraw).
    event RoiClaimed(address indexed user, uint256 gross, uint256 netIfWithdrawNow, uint256 matchingPaid);
    event PositionClosed(address indexed user);
    event Emergency(bool on);
    event Queued(uint8 kind, address indexed user, uint256 amount);
    event QueuePaid(address indexed user, uint256 amount);
    event RankPaid(address indexed user, uint8 rank, uint256 amount);
    event ProtocolFee(address indexed to, uint256 amount, uint8 kind);
    /// @param user Depositor whose network payout had no eligible receiver (or partial level skips).
    event ReferralRewardsLost(address indexed user, uint256 grossAdded);
    /// @param user ROI claimant; matching share skipped because uplines were inactive or absent.
    event RoiMatchingLost(address indexed user, uint256 grossAdded);
    event ReferralIncomeAccrued(address indexed user, uint256 grossAdded, uint8 kind);
    event ReferralIncomeClaimed(address indexed user, uint256 gross, uint256 netIfWithdrawNow);
    /// @param fromUser Wallet that claimed ROI; matching share is credited to `receiver`'s pending balance.
    event RoiMatchingAccrued(address indexed receiver, uint256 grossAdded, address indexed fromUser);
    event RoiMatchingClaimed(address indexed user, uint256 gross, uint256 netIfWithdrawNow);
    /// @param grossAdded Gross amount added to `withdrawableGross` (no fee on claim).
    event WithdrawBalanceCredited(address indexed user, uint256 grossAdded);
    /// @param grossWithdrawn Gross debited from `withdrawableGross`; `netToUser` is sent to wallet after 5% withdraw fee.
    event RewardsWithdrawn(address indexed user, uint256 grossWithdrawn, uint256 netToUser);

    constructor(address token_, address root_, address feeWallet_, address hedgeVault_) {
        token = IVaultExToken(token_);
        if (token_ == address(0) || root_ == address(0)) revert ZeroAddress();
        if (feeWallet_ == address(0) || hedgeVault_ == address(0)) revert ZeroAddress();
        owner = msg.sender;
        rootSponsor = root_;
        feeWallet  = feeWallet_;
        hedgeVault = hedgeVault_;
        // Root is a protocol sink for orphan referrals; must exist for payout walks. Self-sponsored upline walks stop at `nextSp == sp`.
        User storage ru = users[root_];
        ru.exists = true;
        ru.sponsor = root_;
        registerIdNonce = 1;
        registerIdOf[root_] = REGISTER_ID_MIN;
        userByRegisterId[REGISTER_ID_MIN] = root_;
    }

    /// @dev Pseudo-random unused id in [REGISTER_ID_MIN, REGISTER_ID_MAX]. Not a secure RNG; sufficient for referral codes.
    function _mintRandomRegisterId(address user) internal returns (uint256 rid) {
        uint256 span = REGISTER_ID_MAX - REGISTER_ID_MIN + 1;
        for (uint256 i = 0; i < 256; ) {
            uint256 h = uint256(
                keccak256(
                    abi.encodePacked(
                        block.prevrandao,
                        block.timestamp,
                        block.number,
                        user,
                        address(this),
                        registerIdNonce,
                        i
                    )
                )
            );
            rid = REGISTER_ID_MIN + (h % span);
            if (userByRegisterId[rid] == address(0)) {
                unchecked {
                    ++registerIdNonce;
                }
                return rid;
            }
            unchecked {
                ++i;
            }
        }
        revert RegisterIdsExhausted();
    }

    /// @dev Solidity does not allow fixed arrays as `constant` state vars; use pure lookups (Remix-compatible).
    function _levelWeight(uint256 idx) internal pure returns (uint16) {
        if (idx == 0) return 400;
        if (idx == 1) return 200;
        if (idx < 4) return 150; // idx 2-3
        if (idx < 6) return 100; // idx 4-5
        if (idx < 9) return 75;  // idx 6-8
        if (idx < 13) return 50; // idx 9-12
        return 25;               // idx 13
    }

    /// @dev Rank thresholds span 500–5000 (token units); tune for production if needed.
    function _rankVolume(uint8 rank) internal pure returns (uint256) {
        if (rank < 6) return uint256(rank + 1) * 500e18; // 500,1000,...,3000
        if (rank == 6) return 4_000e18;
        if (rank == 7) return 5_000e18;
        return 0;
    }

    function _rankPayout(uint8 rank) internal pure returns (uint256) {
        if (rank >= 8) return 0;
        return uint256(rank + 1) * 100e18;
    }

    function _rankMinCycle(uint8 rank) internal pure returns (uint8) {
        rank; // Silence "unused parameter" while preserving the same signature.
        return 1;
    }

    /// @dev Applies a 50%-per-source cap for rank qualification:
    ///      each individual downline contributor contributes at most `rankRequirement / 2`.
    function _rankUsableBusiness(address user_, uint8 rank) internal view returns (uint256 usable) {
        uint256 required = _rankVolume(rank);
        uint256 perSourceCap = required / 2;
        address[] storage sources = rankContributionSources[user_];
        for (uint256 i = 0; i < sources.length; ) {
            uint256 sourceBiz = contributorVolume[user_][sources[i]];
            if (sourceBiz > perSourceCap) sourceBiz = perSourceCap;
            usable += sourceBiz;
            if (usable >= required) return required;
            unchecked {
                ++i;
            }
        }
    }

    function _rankLegEligible(address user_, uint8 rank) internal view returns (bool) {
        return _rankUsableBusiness(user_, rank) >= _rankVolume(rank);
    }

    function _creditWithdrawableGross(address user, uint256 grossAmt) internal {
        if (grossAmt == 0) return;
        withdrawableGross[user] += grossAmt;
        emit WithdrawBalanceCredited(user, grossAmt);
    }
}

