// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./VaultExQueue.sol";

contract VaultExTreasuryEmergency is VaultExQueue {
    /// @dev Gas cap per call for `fundVault` queue draining.
    uint256 private constant _MAX_SYNC_QUEUE_ITEMS = 256;

    constructor(address token_, address root_, address feeWallet_, address hedgeVault_) VaultExQueue(token_, root_, feeWallet_, hedgeVault_) {}

    /// @notice Pull `amount` from `msg.sender` via `transferFrom` (approve first), then refresh emergency state
    ///         and optionally pay up to `maxQueueItems` priority-queue payouts while balance allows.
    /// @param maxQueueItems 0 = only `_pokeEmergency()`; 1–256 = flush at most this many queue payments first.
    function fundVault(uint256 amount, uint256 maxQueueItems) external {
        if (amount == 0) revert ZeroAmount();
        if (!token.transferFrom(msg.sender, address(this), amount)) revert TransferIn();
        if (maxQueueItems > _MAX_SYNC_QUEUE_ITEMS) maxQueueItems = _MAX_SYNC_QUEUE_ITEMS;
        if (maxQueueItems > 0) _autoFlushQueue(maxQueueItems);
        else _pokeEmergency();
    }
}

