// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./VaultExConfig.sol";

contract VaultExUsers is VaultExConfig {
    constructor(address token_, address root_, address feeWallet_, address hedgeVault_)
        VaultExConfig(token_, root_, feeWallet_, hedgeVault_)
    {}

    function _isValidRegisterId(uint256 id) internal pure returns (bool) {
        return id >= REGISTER_ID_MIN && id <= REGISTER_ID_MAX;
    }

    function _resolveSponsorByRegisterId(uint256 sponsorRegisterId) internal view returns (address) {
        if (sponsorRegisterId == 0) return rootSponsor;
        if (!_isValidRegisterId(sponsorRegisterId)) revert BadSponsorId();
        address s = userByRegisterId[sponsorRegisterId];
        if (s == address(0) || s == msg.sender || !users[s].exists) return rootSponsor;
        return s;
    }

    function getUser(address a) external view returns (
        address sponsor,
        bool exists,
        bool blocked,
        uint8 maxCycle,
        uint32 directs,
        bool hasActive,
        uint256 groupVolume,
        uint256 maxLeg,
        uint256 withdrawn,
        uint16 rankMask
    ) {
        User storage u = users[a];
        return (
            u.sponsor,
            u.exists,
            u.blocked,
            u.maxCycleReached,
            u.directs,
            u.hasActive,
            u.groupVolume,
            u.maxLegVolume,
            u.totalWithdrawn,
            u.rankClaimedMask
        );
    }

    function getPosition(address a) external view returns (
        uint128 amount,
        uint64 openedAt,
        uint64 lastRoiAt,
        uint8 cycle,
        bool active,
        bool principalWithdrawn,
        uint128 paidTotal,
        uint128 roiPaid,
        uint64 closedAt
    ) {
        Position storage p = activePosition[a];
        return (
            p.amount,
            p.openedAt,
            p.lastRoiAt,
            p.cycle,
            p.active,
            p.principalWithdrawn,
            p.paidTotal,
            p.roiPaid,
            p.closedAt
        );
    }

    function getRankDetails(address u) external view returns (string[] memory keys, uint256[] memory values) {
        User storage usr = users[u];
        keys = new string[](13);
        values = new uint256[](13);
        // Keep short labels to minimize embedded runtime string data.
        keys[0] = "a";
        values[0] = usr.groupVolume;
        keys[1] = "b";
        values[1] = usr.maxLegVolume;
        keys[2] = "c";
        values[2] = usr.maxCycleReached;
        keys[3] = "d";
        values[3] = usr.rankClaimedMask;
        keys[4] = "e";
        values[4] = pendingRankClaim[u];
        keys[5] = "f";
        values[5] = usr.hasActive && activePosition[u].active ? 1 : 0;
        keys[6] = "g";
        values[6] = 0;
        keys[7] = "h";
        values[7] = 0;
        keys[8] = "i";
        values[8] = 0;
        keys[9] = "j";
        values[9] = 0;
        keys[10] = "k";
        values[10] = 0;
        keys[11] = "l";
        values[11] = 0;
        keys[12] = "m";
        values[12] = 0;
    }
}

