// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./VaultExTreasuryEmergency.sol";

contract VaultExViews is VaultExTreasuryEmergency {
    constructor(address token_, address root_, address feeWallet_, address hedgeVault_) VaultExTreasuryEmergency(token_, root_, feeWallet_, hedgeVault_) {}

    function contractTokenBalance() external view returns (uint256) {
        return token.balanceOf(address(this));
    }

    /// @notice Gross referral (direct+level) not paid on this address's deposits because uplines had no active position.
    /// @notice Gross ROI-on-ROI matching not paid when uplines are not in active ROI accrual (or absent / short chain).
    function getLostRewardGross(address u) external view returns (uint256 referral, uint256 roiMatching) {
        return (lostReferralGross[u], lostRoiMatchingGross[u]);
    }

    /// @notice Wallets that registered with `u` as sponsor (direct downline only), in registration order.
    function getDirectReferrals(address u) external view returns (address[] memory) {
        return directReferrals[u];
    }

    /// @notice Pending direct and level income currently accrued for `u` (gross) and preview net if withdrawn in one go after claim (before cap).
    /// @dev For the amount that would actually be credited this call, use `previewClaimReferralIncome`.
    function getPendingReferralIncome(address u)
        external
        view
        returns (uint256 directGross, uint256 levelGross, uint256 totalGross, uint256 netAfterFee)
    {
        directGross = pendingDirectReferralGross[u];
        levelGross = pendingLevelIncomeGross[u];
        totalGross = directGross + levelGross;
        (netAfterFee, ) = _previewTxFee(totalGross);
    }

    /// @notice Read-only preview of `claimReferralIncome()` for dashboards (same cap rules as the claim).
    /// @dev `reasonCode`: 0=OK, 1=user-invalid, 2=no-active, 3=nothing-pending, 4=cap-blocks-claim, 5=unused.
    /// @dev `wouldPayInstantly` is true when `claimReferralIncome` would credit `withdrawableGross` in this tx (not emergency-queued and pool has liquidity).
    function previewClaimReferralIncome(address u)
        external
        view
        returns (
            uint256 directGross,
            uint256 levelGross,
            uint256 totalPendingGross,
            uint256 payableGross,
            uint256 netToUser,
            uint256 protocolFee,
            bool wouldPayInstantly,
            uint8 reasonCode
        )
    {
        directGross = pendingDirectReferralGross[u];
        levelGross = pendingLevelIncomeGross[u];
        totalPendingGross = directGross + levelGross;

        User storage usr = users[u];
        if (!usr.exists || usr.blocked) {
            return (directGross, levelGross, totalPendingGross, 0, 0, 0, false, 1);
        }
        Position storage p = activePosition[u];
        if (!p.active && u != rootSponsor) {
            return (directGross, levelGross, totalPendingGross, 0, 0, 0, false, 2);
        }
        if (totalPendingGross == 0) {
            return (directGross, levelGross, 0, 0, 0, 0, false, 3);
        }
        payableGross = _capNonRoiCredit(u, p, totalPendingGross);
        if (payableGross == 0) {
            return (directGross, levelGross, totalPendingGross, 0, 0, 0, false, 4);
        }

        (netToUser, protocolFee) = _previewTxFee(payableGross);
        wouldPayInstantly = !emergencyMode && token.balanceOf(address(this)) >= payableGross;
        reasonCode = 0;
    }

    /// @notice Breadth-first list of downline addresses under `root`, excluding `root`. Capped by `maxDepth` and `maxNodes`.
    /// @dev Stops early if the internal queue fills; use subgraph or off-chain walks for very large trees.
    function getDownlineReferrals(address root, uint256 maxDepth, uint256 maxNodes) external view returns (address[] memory out) {
        if (!users[root].exists || maxDepth == 0 || maxNodes == 0) return new address[](0);
        if (maxDepth > 32) maxDepth = 32;
        uint256 cap = maxNodes > 512 ? maxNodes : 512;
        if (cap > 4096) cap = 4096;
        address[] memory q = new address[](cap);
        uint256[] memory depth = new uint256[](cap);
        uint256 head;
        uint256 tail;
        address[] memory dirs = directReferrals[root];
        for (uint256 i = 0; i < dirs.length; ) {
            if (tail >= cap) break;
            q[tail] = dirs[i];
            depth[tail] = 1;
            unchecked {
                ++tail;
                ++i;
            }
        }
        address[] memory buf = new address[](maxNodes);
        uint256 n;
        while (head < tail && n < maxNodes) {
            address a = q[head];
            uint256 d = depth[head];
            unchecked {
                ++head;
            }
            buf[n++] = a;
            if (d < maxDepth && n < maxNodes && tail < cap) {
                dirs = directReferrals[a];
                for (uint256 j = 0; j < dirs.length; ) {
                    if (tail >= cap) break;
                    q[tail] = dirs[j];
                    depth[tail] = d + 1;
                    unchecked {
                        ++tail;
                        ++j;
                    }
                }
            }
        }
        out = new address[](n);
        for (uint256 k = 0; k < n; ) {
            out[k] = buf[k];
            unchecked {
                ++k;
            }
        }
    }

    /// @notice Sponsor chain above `u`: first entry is `u`'s direct sponsor, then sponsor-of-sponsor, etc.
    /// @dev Stops at root/self-sponsor, missing users, or `maxDepth` (clamped to 256).
    function getUplineChain(address u, uint256 maxDepth) external view returns (address[] memory chain) {
        if (maxDepth == 0 || maxDepth > 256) maxDepth = 256;
        address[] memory buf = new address[](maxDepth);
        uint256 n;
        address cur = u;
        for (uint256 i = 0; i < maxDepth; ) {
            address sp = users[cur].sponsor;
            if (sp == address(0) || sp == cur || !users[sp].exists) break;
            buf[n++] = sp;
            cur = sp;
            unchecked {
                ++i;
            }
        }
        chain = new address[](n);
        for (uint256 j = 0; j < n; ) {
            chain[j] = buf[j];
            unchecked {
                ++j;
            }
        }
    }

    /// @notice Rank-claim diagnostics for UIs/debugging (stack-safe for Remix compiler).
    /// @dev `pendingRankRaw`: 0 = none pending, otherwise (`rank + 1`) currently queued.
    /// @dev `reasonCode`:
    ///      0=OK, 1=bad-rank, 2=user-invalid, 3=no-active, 4=already-claimed, 5=already-pending,
    ///      6=volume-low, 7=cycle-low, 8=5x-cap-blocked, 9=unused, 10=pool-low.
    function previewClaimRank(address u, uint8 rank)
        external
        view
        returns (
            uint256 payoutGross,
            uint256 payoutNet,
            bool emergencyWillQueue,
            bool claimableNow,
            uint8 reasonCode,
            uint8 pendingRankRaw
        )
    {
        pendingRankRaw = pendingRankClaim[u];
        if (rank >= 8) return (0, 0, false, false, 1, pendingRankRaw);

        User storage usr = users[u];
        if (!usr.exists || usr.blocked) return (0, 0, false, false, 2, pendingRankRaw);
        Position storage p = activePosition[u];
        if (!usr.hasActive || !p.active) return (0, 0, false, false, 3, pendingRankRaw);
        if ((usr.rankClaimedMask & uint16(1 << rank)) != 0) return (0, 0, false, false, 4, pendingRankRaw);
        if (pendingRankRaw != 0) return (0, 0, false, false, 5, pendingRankRaw);
        if (!_rankLegEligible(u, rank)) return (0, 0, false, false, 6, pendingRankRaw);
        if (usr.maxCycleReached < _rankMinCycle(rank)) return (0, 0, false, false, 7, pendingRankRaw);

        payoutGross = _rankPayout(rank);
        if (!emergencyMode) {
            payoutGross = _capNonRoiCredit(u, p, payoutGross);
            if (payoutGross == 0) return (0, 0, false, false, 8, pendingRankRaw);
        }
        (payoutNet, ) = _previewTxFee(payoutGross);
        if (!emergencyMode && token.balanceOf(address(this)) < payoutGross) return (payoutGross, payoutNet, false, false, 10, pendingRankRaw);

        emergencyWillQueue = emergencyMode;
        claimableNow = !emergencyMode;
        reasonCode = 0;
    }

    /// @notice Rank bonus income snapshot (gross + net after 5% fee preview).
    /// @dev If a rank is emergency-queued (`pendingRankClaim`), returns that bonus only; no other rank can be claimed until it pays out.
    ///      Otherwise returns totals over unclaimed ranks that pass volume/cycle gates (same as `claimRank`).
    /// @param queuedRankIndex Rank 0–7 if a bonus is queued; `8` if none.
    function getRankIncome(address u)
        external
        view
        returns (
            uint256 queuedRankBonusGross,
            uint256 queuedNetAfterFee,
            uint8 queuedRankIndex,
            uint256 additionalClaimableGrossAfterCap,
            uint256 additionalNetAfterFee
        )
    {
        User storage usr = users[u];
        if (!usr.exists || usr.blocked) {
            return (0, 0, 8, 0, 0);
        }

        uint8 raw = pendingRankClaim[u];
        if (raw != 0) {
            uint8 r = raw - 1;
            uint256 g = _rankPayout(r);
            (uint256 n, ) = _previewTxFee(g);
            return (g, n, r, 0, 0);
        }

        Position storage p = activePosition[u];
        if (!usr.hasActive || !p.active) {
            return (0, 0, 8, 0, 0);
        }

        uint256 sumGross;
        for (uint8 r = 0; r < 8; ) {
            if ((usr.rankClaimedMask & uint16(1 << r)) != 0) {
                unchecked {
                    ++r;
                }
                continue;
            }
            if (!_rankLegEligible(u, r)) {
                unchecked {
                    ++r;
                }
                continue;
            }
            if (usr.maxCycleReached < _rankMinCycle(r)) {
                unchecked {
                    ++r;
                }
                continue;
            }
            sumGross += _rankPayout(r);
            unchecked {
                ++r;
            }
        }
        uint256 cap = uint256(p.amount) * POSITION_EARNINGS_CAP_MUL;
        uint256 paid = uint256(p.paidTotal);
        uint256 room = cap > paid ? cap - paid : 0;
        additionalClaimableGrossAfterCap = sumGross < room ? sumGross : room;
        (additionalNetAfterFee, ) = _previewTxFee(additionalClaimableGrossAfterCap);
        return (0, 0, 8, additionalClaimableGrossAfterCap, additionalNetAfterFee);
    }

    /// @notice Returns the Unix timestamp at which `user`'s active position unlocks.
    ///         Returns 0 if the user has no active position.
    function cycleEndsAt(address user) external view returns (uint256) {
        Position storage p = activePosition[user];
        if (!p.active) return 0;
        return _cycleEndsAt(p);
    }

    /// @notice Read-only preview of `claimRoi()` for dashboards.
    ///
    ///  Reflects the new lifecycle:
    ///  • If `paidTotal >= 5×` or `roiPaid >= 2×`: claimable = false (position is expected to close immediately).
    ///  • If the position is active and under the caps: normal ROI preview.
    ///  • Post-close (`!p.active`): shows pro-rata closing ROI still claimable (bounded by ROI cap and earnings cap).
    ///
    /// @param u User address (same as `claimRoi` caller).
    /// @return gross             Gross ROI for accrued claim periods (capped), before pool clamp.
    /// @return netToUser         Preview: net to wallet if user `withdraw`s this gross in one tx (5% fee on withdraw).
    /// @return matchingBudget    Notional gross matching (20% of `gross`) credited to uplines' pending balances on claim (not paid in same tx).
    /// @return periodsElapsed    Full claim periods since `lastRoiAt` (uncapped).
    /// @return periodsPayable    Periods that count toward `gross` after caps (<= periodsElapsed).
    /// @return claimable         True if `claimRoi()` would succeed and credit `withdrawableGross`.
    /// @return earliestClaimAt   `lastRoiAt + ROI_CLAIM_PERIOD` when active and under caps; 0 otherwise.
    function previewClaimRoi(address u)
        public
        view
        returns (
            uint256 gross,
            uint256 netToUser,
            uint256 matchingBudget,
            uint256 periodsElapsed,
            uint256 periodsPayable,
            bool    claimable,
            uint64  earliestClaimAt
        )
    {
        if (users[u].blocked) return (0, 0, 0, 0, 0, false, 0);

        Position storage p = activePosition[u];
        if (!p.active) {
            return _previewClaimRoiClosed(p);
        }

        uint256 totalCap = uint256(p.amount) * POSITION_EARNINGS_CAP_MUL;
        if (emergencyMode) totalCap = uint256(p.amount);
        uint256 roiCap   = uint256(p.amount) * POSITION_ROI_CAP_MUL;
        if (p.paidTotal >= totalCap || p.roiPaid >= roiCap) {
            return (0, 0, 0, 0, 0, false, 0);
        }

        return _previewClaimRoiAccruing(u, p, totalCap);
    }

    /// @notice Read-only claimable ROI income for `u` using current `claimRoi` constraints.
    /// @dev `accruedGross` is the raw preview amount; `claimableGross` is zeroed when claim would fail now
    ///      (for example due to pool liquidity checks).
    function getClaimableRoiIncome(address u)
        external
        view
        returns (
            uint256 claimableGross,
            uint256 accruedGross,
            bool canClaimNow,
            uint64 earliestClaimAt
        )
    {
        (
            uint256 gross,
            ,
            ,
            ,
            ,
            bool claimable,
            uint64 earliest
        ) = previewClaimRoi(u);

        accruedGross = gross;
        canClaimNow = claimable;
        earliestClaimAt = earliest;
        claimableGross = claimable ? gross : 0;
    }

    /// @dev Post-close branch only — keeps `previewClaimRoi` stack-shallow for Remix / legacy codegen.
    function _previewClaimRoiClosed(Position storage p)
        private
        view
        returns (
            uint256 gross,
            uint256 netToUser,
            uint256 matchingBudget,
            uint256 periodsElapsed,
            uint256 periodsPayable,
            bool claimable,
            uint64 earliestClaimAt
        )
    {
        if (p.amount == 0) return (0, 0, 0, 0, 0, false, 0);

        uint256 totalCap = uint256(p.amount) * POSITION_EARNINGS_CAP_MUL;
        if (emergencyMode) totalCap = uint256(p.amount);
        uint256 roiCap = uint256(p.amount) * POSITION_ROI_CAP_MUL;
        if (p.closedAt <= p.lastRoiAt || p.roiPaid >= roiCap) {
            return (0, 0, 0, 0, 0, false, 0);
        }

        uint256 roiRoom = roiCap > uint256(p.roiPaid) ? roiCap - uint256(p.roiPaid) : 0;
        uint256 totalRoom = totalCap > uint256(p.paidTotal) ? totalCap - uint256(p.paidTotal) : 0;
        uint256 room = roiRoom < totalRoom ? roiRoom : totalRoom;
        gross = _closingRoiGross(p, room);
        if (gross == 0) return (0, 0, 0, 0, 0, false, 0);

        (netToUser, ) = _previewTxFee(gross);
        if (emergencyMode) {
            matchingBudget = 0;
        } else {
            matchingBudget = gross * 20 / 100;
        }
        claimable = token.balanceOf(address(this)) >= gross;
    }

    /// @dev Thin wrapper so the caller does not hold `roiQ` and call args on the stack together with 7 returns.
    function _accruedRoiGrossForUser(
        Position storage p,
        uint256 elapsed,
        uint256 totalCap,
        address u
    ) private view returns (uint256 gross, uint256 periodsPayable) {
        return _accruedRoiGross(p, elapsed, totalCap, roiQueuedGross[u]);
    }

    /// @dev Post-accrual fee + pool check — separate stack frame.
    function _previewRoiDistributable(uint256 gross)
        private
        view
        returns (uint256 netToUser, uint256 matchingBudget, bool claimable)
    {
        (netToUser, ) = _previewTxFee(gross);
        if (emergencyMode) {
            matchingBudget = 0;
        } else {
            matchingBudget = gross * 20 / 100;
        }
        claimable = token.balanceOf(address(this)) >= gross;
    }

    /// @dev Active position accrual preview — helpers + scoped block avoid "stack too deep" without viaIR.
    function _previewClaimRoiAccruing(address u, Position storage p, uint256 totalCap)
        private
        view
        returns (
            uint256 gross,
            uint256 netToUser,
            uint256 matchingBudget,
            uint256 periodsElapsed,
            uint256 periodsPayable,
            bool claimable,
            uint64 earliestClaimAt
        )
    {
        earliestClaimAt = uint64(uint256(p.lastRoiAt) + ROI_CLAIM_PERIOD);
        uint256 pe;
        {
            uint256 elapsed = block.timestamp - uint256(p.lastRoiAt);
            if (elapsed < ROI_CLAIM_PERIOD) {
                return (0, 0, 0, 0, 0, false, earliestClaimAt);
            }
            pe = elapsed / ROI_CLAIM_PERIOD;
            (gross, periodsPayable) = _accruedRoiGrossForUser(p, elapsed, totalCap, u);
        }
        periodsElapsed = pe;
        if (gross == 0) {
            return (0, 0, 0, periodsElapsed, 0, false, earliestClaimAt);
        }
        (netToUser, matchingBudget, claimable) = _previewRoiDistributable(gross);
    }
}

contracts/VaultExVolumeLifecycle.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./VaultExAntiAbuse.sol";

/// @dev Volume propagation, C1 obligation tracking, queue shift, and position close lifecycle.
contract VaultExVolumeLifecycle is VaultExAntiAbuse {
    constructor(address token_, address root_, address feeWallet_, address hedgeVault_) VaultExAntiAbuse(token_, root_, feeWallet_, hedgeVault_) {}

    // ─── Helpers ────────────────────────────────────────────────────────────

    /// @dev Timestamp at which the cycle ends and the position may auto-close.
    function _cycleEndsAt(Position storage p) internal view returns (uint256) {
        return uint256(p.openedAt) + cycleDuration[p.cycle];
    }

    /// @dev True while the cycle duration has not yet elapsed (position cannot auto-close).
    function _isTimeLocked(Position storage p) internal view returns (bool) {
        return block.timestamp < _cycleEndsAt(p);
    }

    // ─── Volume ─────────────────────────────────────────────────────────────

    function _bumpTurnover(uint256 d) internal {
        unchecked {
            turnover += d;
            if (turnover > athTurnover) athTurnover = turnover;
        }
    }

    function _c1Paydown(uint256 d) internal {
        if (c1RemainingObligation >= d) c1RemainingObligation -= d;
        else c1RemainingObligation = 0;
    }

    function _propagateVolume(address user, address firstSponsor, uint256 amount) internal {
        // `legVolume[sponsor][directLeg]` tracks branch business for legacy leg analytics.
        // `contributorVolume[ancestor][user]` tracks per-user source contribution for rank caps.
        address child = user;
        address sp = firstSponsor;
        while (sp != address(0) && users[sp].exists) {
            users[sp].groupVolume += amount;
            contributorVolume[sp][user] += amount;
            uint256 nv = legVolume[sp][child] + amount;
            legVolume[sp][child] = nv;
            if (nv > users[sp].maxLegVolume) users[sp].maxLegVolume = nv;

            address nextSp = users[sp].sponsor;
            // Root (or any user) with sponsor == self — common after register(0) (root id) → sponsor = rootSponsor.
            // Without this, the walk never terminates and deposit reverts with out-of-gas.
            if (nextSp == sp) break;
            child = sp;
            sp = nextSp;
        }
    }

    function _shiftPriorityQueue(uint8 priority) internal {
        QueueItem[] storage q = priorityQueues[priority];
        uint256 n = q.length;
        if (n == 0) return;
        for (uint256 i = 1; i < n; i++) {
            q[i - 1] = q[i];
        }
        q.pop();
    }

    function _pushPriorityQueue(QueueItem memory item) internal {
        if (item.priority < 1 || item.priority > 8) revert InvalidQueuePriority();
        priorityQueues[item.priority].push(item);
        pendingQueuedWithdrawals += item.amount;
    }

    /// @dev ROI emergency bucket: C1 still recovering capital → P1; C1 otherwise → P7; cycles 2–6 → P2–P6.
    function _roiEmergencyPriority(address u, Position storage p) internal view returns (uint8) {
        uint8 c = p.cycle;
        if (c < 1 || c > 6) revert InvalidCycle();
        if (c == 1) {
            if (users[u].totalWithdrawn < uint256(p.amount)) return PQ_C1_RECOVERY;
            return PQ_NETWORK;
        }
        return c;
    }

    /// @dev Pays the front of priorities 1..8 up to `maxItems` transfers; used by `flushQueue` and after inflows.
    function _flushPriorityQueues(uint256 maxItems) internal {
        if (maxItems == 0) return;
        uint256 processed;
        for (uint8 pri = 1; pri <= 8 && processed < maxItems; pri++) {
            while (processed < maxItems && priorityQueues[pri].length > 0) {
                QueueItem memory item = priorityQueues[pri][0];
                address payee = item.user;
                uint256 amt = item.amount;
                bool cred = item.creditPosition;

                uint256 grossOut = amt;
                bool isRoiQueue = (!cred && item.priority >= 1 && item.priority <= 6);

                // Emergency rule: do not pay non-ROI rewards (network/rank).
                // Keep them queued until emergency mode is cleared.
                if (emergencyMode && item.priority >= PQ_NETWORK) break;

                if (isRoiQueue) {
                    Position storage pR = activePosition[payee];
                    if (!pR.active) {
                        _shiftPriorityQueue(pri);
                        pendingQueuedWithdrawals -= amt;
                        if (amt >= roiQueuedGross[payee]) roiQueuedGross[payee] = 0;
                        else roiQueuedGross[payee] -= uint128(amt);
                        unchecked {
                            ++processed;
                        }
                        continue;
                    }
                    grossOut = amt;
                    if (emergencyMode) {
                        // Emergency cap: total reward credits must not exceed principal.
                        uint256 emergencyRoom = uint256(pR.amount) > uint256(pR.paidTotal)
                            ? uint256(pR.amount) - uint256(pR.paidTotal)
                            : 0;
                        if (emergencyRoom == 0) {
                            _shiftPriorityQueue(pri);
                            pendingQueuedWithdrawals -= amt;
                            if (amt >= roiQueuedGross[payee]) roiQueuedGross[payee] = 0;
                            else roiQueuedGross[payee] -= uint128(amt);
                            _closeIfNeeded(payee, pR);
                            unchecked {
                                ++processed;
                            }
                            continue;
                        }
                        if (grossOut > emergencyRoom) grossOut = emergencyRoom;
                    }
                } else if (cred) {
                    Position storage p = activePosition[payee];
                    if (item.priority == PQ_RANK && item.rankMeta != RANK_META_NONE) {
                        if (!p.active) {
                            _shiftPriorityQueue(pri);
                            pendingQueuedWithdrawals -= amt;
                            pendingRankClaim[payee] = 0;
                            unchecked {
                                ++processed;
                            }
                            continue;
                        }
                        grossOut = _capNonRoiCredit(payee, p, amt);
                        if (grossOut == 0) {
                            _shiftPriorityQueue(pri);
                            pendingQueuedWithdrawals -= amt;
                            pendingRankClaim[payee] = 0;
                            unchecked {
                                ++processed;
                            }
                            continue;
                        }
                    } else if (p.active) {
                        grossOut = _capNonRoiCredit(payee, p, amt);
                        if (grossOut == 0) break;
                    } else if (payee == rootSponsor) {
                        grossOut = _capNonRoiCredit(payee, p, amt);
                        if (grossOut == 0) break;
                    } else {
                        _shiftPriorityQueue(pri);
                        pendingQueuedWithdrawals -= amt;
                        unchecked {
                            ++processed;
                        }
                        continue;
                    }
                }

                if (token.balanceOf(address(this)) < grossOut) break;

                _shiftPriorityQueue(pri);
                pendingQueuedWithdrawals -= amt;

                bool rankPaysWallet = cred && item.priority == PQ_RANK && item.rankMeta != RANK_META_NONE;
                if (rankPaysWallet) {
                    (uint256 netAmt, ) = _netAfterTxFee(grossOut, 5);
                    if (!token.transfer(payee, netAmt)) revert TransferOut();
                } else {
                    _creditWithdrawableGross(payee, grossOut);
                }
                if (isRoiQueue) {
                    Position storage p2 = activePosition[payee];
                    p2.roiPaid += uint128(grossOut);
                    p2.paidTotal += uint128(grossOut);
                    if (p2.cycle == 1) _c1Paydown(grossOut);
                    // Full queue item is consumed here; any overflow above cap is dropped as lost.
                    if (amt >= roiQueuedGross[payee]) roiQueuedGross[payee] = 0;
                    else roiQueuedGross[payee] -= uint128(amt);
                    _closeIfNeeded(payee, p2);
                } else if (cred) {
                    Position storage p3 = activePosition[payee];
                    if (p3.active) {
                        if (item.priority == PQ_RANK && item.rankMeta != RANK_META_NONE) {
                            uint8 r = item.rankMeta;
                            p3.paidTotal += uint128(grossOut);
                            if (p3.cycle == 1) _c1Paydown(grossOut);
                            users[payee].rankClaimedMask |= uint16(1 << r);
                            pendingRankClaim[payee] = 0;
                            emit RankPaid(payee, r, grossOut);
                        } else {
                            p3.paidTotal += uint128(grossOut);
                            if (p3.cycle == 1) _c1Paydown(grossOut);
                        }
                        _closeIfNeeded(payee, p3);
                    }
                }

                emit QueuePaid(payee, grossOut);
                unchecked {
                    ++processed;
                }
            }
        }
        _pokeEmergency();
    }

    function _autoFlushQueue(uint256 maxItems) internal {
        _flushPriorityQueues(maxItems);
    }

    function _postStateSync() internal {
        _pokeEmergency();
        _autoFlushQueue(32);
    }

    // ─── Earnings cap helper ─────────────────────────────────────────────────

    /// @dev Caps non-ROI credits (direct, level, matching, rank) only by the total earnings cap (5× principal).
    ///      Returns the portion of `gross` that can actually be credited right now.
    ///      Returns 0 when the total earnings cap is already reached.
    /// @dev Root sponsor bypasses this cap check (still frozen entirely while `emergencyMode`).
    function _capNonRoiCredit(address user, Position storage p, uint256 gross) internal view returns (uint256) {
        // Emergency mode freeze: only ROI should flow (up to principal-equivalent total rewards).
        if (emergencyMode) return 0;
        if (user == rootSponsor) return gross;
        uint256 cap = uint256(p.amount) * POSITION_EARNINGS_CAP_MUL;
        uint256 paid = uint256(p.paidTotal);
        if (paid >= cap || gross == 0) return 0;
        uint256 room = cap - paid;
        return gross < room ? gross : room;
    }

    // ─── Position lifecycle ──────────────────────────────────────────────────

    /// @dev Finalize the position when either cap is reached OR cycle duration has elapsed.
    ///      This makes cap-hit positions immediately inactive and eligible for next-cycle deposit.
    function _closeIfNeeded(address user_, Position storage p) internal {
        // Keep close criteria aligned with ROI accrual/preview math:
        // emergency mode clamps total rewards at principal (1x), otherwise normal earnings cap (5x).
        uint256 earnCap = emergencyMode
            ? uint256(p.amount)
            : uint256(p.amount) * POSITION_EARNINGS_CAP_MUL;
        uint256 roiCap = uint256(p.amount) * POSITION_ROI_CAP_MUL;
        if (uint256(p.paidTotal) >= earnCap || uint256(p.roiPaid) >= roiCap || !_isTimeLocked(p)) {
            _finalizeClose(user_, p);
        }
    }

    function _finalizeClose(address user_, Position storage p) internal {
        if (!p.active) return;

        p.active = false;
        p.closedAt = uint64(block.timestamp);
        p.principalWithdrawn = true;
        // Closing a cycle is a hard stop for new accrual only.
        // Already-claimed balances (e.g. withdrawable credits / queued claims) remain intact.
        users[user_].hasActive = false;
        users[user_].lastClosedCycle = p.cycle;
        users[user_].lastPrincipal = p.amount;
        if (p.cycle == 1) {
            uint256 rem = uint256(p.amount) * C1_OBLIGATION_MUL - uint256(p.paidTotal);
            if (rem > 0 && c1RemainingObligation > rem) c1RemainingObligation -= rem;
            else if (rem > 0) c1RemainingObligation = 0;
        }
        emit PositionClosed(user_);
        _postStateSync();
    }

    // ─── Emergency mode ──────────────────────────────────────────────────────
    /// @dev Distribution wallet = contract token balance available for payouts.
    function _distributionWallet() internal view returns (uint256) {
        return token.balanceOf(address(this));
    }

    function _setEmergency(bool) internal pure {
        revert EmergencyManualDisabled();
    }

    /// @notice Emergency when the contract balance is empty (no payout liquidity), or — if there is a
    ///         payout queue — when it holds less than 25% of outstanding queued gross. Cleared when
    ///         balance ≥ 25% of `pendingQueuedWithdrawals`, or when nothing is queued and the contract has funds.
    ///
    /// @dev Customized rules:
    ///      - Emergency ON  when contract token balance < 5 tokens.
    ///      - Emergency OFF when pending queued withdrawals (principal/ROI/rank/etc. queued) are <= 25% of
    ///        contract token balance AND balance is >= 5 tokens.
    function _pokeEmergency() internal {
        uint256 dist = _distributionWallet();
        uint256 pend = pendingQueuedWithdrawals;

        bool should;
        if (totalDeposits == 0) {
            should = false;
        } else {
            uint256 floor = 5e18;
            if (dist < floor) {
                should = true;
            } else if (pend == 0) {
                should = false;
            } else {
                // Keep emergency ON while pending > 25% of wallet; clear when pending <= 25% of wallet.
                should = pend > (dist * 25) / 100;
            }
        }

        if (should && !emergencyMode) {
            emergencyMode = true;
            emergencyActivatedAt = uint64(block.timestamp);
            emit Emergency(true);
        } else if (!should && emergencyMode) {
            emergencyMode = false;
            emergencyClearedAt = uint64(block.timestamp);
            emit Emergency(false);
        }
    }

    // ─── Pending payout queue (read) ─────────────────────────────────────────

    /// @notice Total FIFO items across all priority queues (priorities 1–8).
    function queueLength() external view returns (uint256) {
        uint256 t;
        for (uint8 i = 1; i <= 8; ) {
            t += priorityQueues[i].length;
            unchecked {
                ++i;
            }
        }
        return t;
    }

    /// @notice Items waiting in one priority queue. `priority` must be 1–8 (else returns 0).
    function queueLengthAt(uint8 priority) external view returns (uint256) {
        if (priority < 1 || priority > 8) return 0;
        return priorityQueues[priority].length;
    }

    /// @notice All eight queue depths: `out[i]` = length of priority `i + 1` (P1…P8).
    function getQueueLengths() external view returns (uint256[8] memory out) {
        for (uint8 i = 1; i <= 8; ) {
            out[i - 1] = priorityQueues[i].length;
            unchecked {
                ++i;
            }
        }
    }
}

contracts/VaultExWithdrawRanks.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./VaultExRoi.sol";

contract VaultExWithdrawRanks is VaultExRoi {
    constructor(address token_, address root_, address feeWallet_, address hedgeVault_) VaultExRoi(token_, root_, feeWallet_, hedgeVault_) {}

    // ─── Rank bonus ──────────────────────────────────────────────────────────

    /// @notice One-time rank bonus (counted toward position 5× earnings cap accounting).
    function claimRank(uint8 rank) external {
        _enforceChain();
        if (rank >= 8) revert BadId();
        User storage u = users[msg.sender];
        if (!u.exists || u.blocked) revert BadId();
        if (!u.hasActive) revert NoActive();
        if ((u.rankClaimedMask & uint16(1 << rank)) != 0) revert RankAlreadyClaimed();
        if (pendingRankClaim[msg.sender] != 0) revert RankClaimAlreadyPending();
        if (!_rankLegEligible(msg.sender, rank)) revert Cap();
        if (u.maxCycleReached < _rankMinCycle(rank)) revert CycleOrder();

        uint256 pay = _rankPayout(rank);
        Position storage p = activePosition[msg.sender];
        if (!p.active) revert NoActive();
        if (!emergencyMode) {
            pay = _capNonRoiCredit(msg.sender, p, pay);
            if (pay == 0) {
                _closeIfNeeded(msg.sender, p);
                if (!p.active) return;
                revert Cap();
            }
        }
        if (emergencyMode) {
            pendingRankClaim[msg.sender] = uint8(rank + 1);
            _pushPriorityQueue(QueueItem(msg.sender, uint128(pay), 4, PQ_RANK, rank, true));
            emit Queued(4, msg.sender, pay);
            _postStateSync();
            _closeIfNeeded(msg.sender, p);
            return;
        }

        if (token.balanceOf(address(this)) < pay) revert PoolLow();

        (uint256 netPay, ) = _netAfterTxFee(pay, 4);
        if (!token.transfer(msg.sender, netPay)) revert TransferOut();
        p.paidTotal += uint128(pay);
        if (p.cycle == 1) _c1Paydown(pay);
        u.rankClaimedMask |= uint16(1 << rank);
        emit RankPaid(msg.sender, rank, pay);

        _closeIfNeeded(msg.sender, p);
        _postStateSync();
    }
}
